12	import org.springframework.dao.DataIntegrityViolationException;
13	import org.springframework.http.HttpStatus;
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.annotation.Transactional;
16	import org.springframework.web.server.ResponseStatusException;
17	
18	/** The periods of a sheet. */
19	@Service
20	public class PeriodService {
21	
22	    private final PeriodRepository periods;
23	    private final SheetService sheets;
24	    private final SheetRepository sheetStore;
25	    private final Audit audit;
26	    private final Rollup rollup;
27	    private final RoleService roles;
28	
29	    public PeriodService(PeriodRepository periods, SheetService sheets, SheetRepository sheetStore, Audit audit,
30	            Rollup rollup, RoleService roles) {
31	        this.roles = roles;
32	        this.periods = periods;
33	        this.sheets = sheets;
34	        this.sheetStore = sheetStore;
35	        this.audit = audit;
36	        this.rollup = rollup;
37	    }
38	
39	    /** The sheet's periods, by from-date. */
40	    @Transactional(readOnly = true)
41	    public List<Period> list(String sheetId) {
42	        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
43	    }
44	
45	    /** Add a period; the name is stored trimmed. Refused when the name is in use on the sheet, the
46	     *  to-date is before the from-date, or it shares a day with another period of the sheet. With no
47	     *  from-date it starts on the sheet's today. */
48	    @Transactional
49	    public Period add(String sheetId, String user, String name, LocalDate fromDate, LocalDate to) {
50	        sheets.load(sheetId, user);
51	        // The sheet is locked so two periods added at the same moment cannot overlap.
52	        LocalDate today = sheetStore.findLockedById(sheetId).orElseThrow().getToday();
53	        LocalDate from = fromDate != null ? fromDate : today;
54	        String trimmed = name.trim();
55	        if (to.isBefore(from)) {
56	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts");
57	        }
58	        List<Period> existing = periods.findBySheetIdOrderByFromDateAsc(sheetId);
59	        if (existing.stream().anyMatch(p -> p.getName().equals(trimmed))) {
60	            throw nameInUse();
61	        }
62	        if (existing.stream().anyMatch(p -> p.overlaps(from, to))) {
63	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another on this sheet");
64	        }
65	        Period added;
66	        try {
67	            added = periods.saveAndFlush(new Period(sheetId, trimmed, from, to));
68	        } catch (DataIntegrityViolationException raced) {
69	            throw nameInUse();
70	        }
71	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName()
72	                + " from=" + added.getFromDate() + " to=" + added.getToDate());
73	        return added;
74	    }
75	
76	    /** Close a period, fixing its due-total as it is now; refused for a role the permission matrix does not allow,
77	     *  and when it is already closed. The sheet is locked so no claim in it changes while its total is taken. */
78	    @Transactional
79	    public Period close(String sheetId, String user, String name) {
80	        sheets.load(sheetId, user);
81	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
82	        if (!sheet.allows("close", roles.roleOf(sheetId, user))) {
83	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
84	        }
85	        Period period = periods.findBySheetIdAndName(sheetId, name)
86	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
87	        if (period.isClosed()) {
88	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
89	        }
90	        period.close(rollup.dueByPersonBetween(sheetId, period.getFromDate(), period.getToDate()));
91	        Period closed = periods.saveAndFlush(period);
92	        BigDecimal total = closed.getClosedTotal();
93	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + closed.getName()
94	                + " total=" + total.toPlainString());
95	        return closed;
96	    }
97	
98	    /** Reopen a closed period, making its due-total live again; only a role the permission matrix allows may (by
99	     *  default a steward), and it is refused when the period is open. */
100	    @Transactional
101	    public Period reopen(String sheetId, String user, String name) {
102	        sheets.load(sheetId, user);
103	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
104	        if (!sheet.allows("reopen", roles.roleOf(sheetId, user))) {
105	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period");
106	        }
107	        Period period = periods.findBySheetIdAndName(sheetId, name)
108	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
109	        if (!period.isClosed()) {
110	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed");
111	        }
112	        period.reopen();
113	        Period reopened = periods.saveAndFlush(period);
114	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + reopened.getName());
115	        return reopened;
116	    }
117	
118	    private static ResponseStatusException nameInUse() {
119	        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet");
120	    }
121	}
