6	/** A dated setting's value from its from-date (yyyy-mm-dd; null: from the beginning of time) until the next one's
7	 *  of the same key; a null value means none. Keys: clerk-limit, floor, terms, terms-A/B/C, late-pct, cap, proof-threshold. */
8	export interface DatedSetting {
9	  key: string;
10	  from: string | null;
11	  value: string | null;
12	}
