14	/** The sheet as the screen shows it: each dated setting as it is in force on its today. */
15	export interface SheetView {
16	  id: string;
17	  /** The sheet's today (yyyy-mm-dd): every date-dependent decision and default uses it, never the clock. */
18	  today: string;
19	  /** A clerk can settle a claim only when its due is at or below this (two decimals); null: no limit. */
20	  clerkLimit: string | null;
21	  /** A claim's live due is at least this (two decimals). */
22	  floor: string;
23	  /** The sheet's terms in days: a claim is due by its date plus these. */
24	  terms: number;
25	  /** The sheet's late percent (two decimals): an overdue claim's due gains this percent of its figure
26	   *  for every full 30 days it is overdue. */
27	  latePct: string;
28	  /** The sheet's policy date (yyyy-mm-dd): a claim dated before it rounds half up, one on or after it half to
29	   *  even; null when it is the sheet's today. */
30	  policyDate: string | null;
31	  /** The sheet's period numbering from (yyyy-mm-dd): while its today is on or after it, a claim opened is
32	   *  numbered within its period; null when off. */
33	  periodNumberingFrom: string | null;
34	  /** The terms in days set per grade; a grade without its own uses the sheet's terms. */
35	  gradeTerms: Partial<Record<Grade, number>>;
36	  /** A person's due-total is at most this (two decimals); null: none. */
37	  cap: string | null;
38	  /** A claim whose due is above this (two decimals), in force on its date, cannot be settled or approved while it
39	   *  has no proofs; null: none. */
40	  proofThreshold: string | null;
41	  /** Every dated value recorded for the settings that carry a figure. */
42	  settings: DatedSetting[];
43	  /** The permission matrix entries set: for an action, the roles that may take it (comma separated); an action
44	   *  missing keeps its standing rule. Not dated. */
45	  permissions: Partial<Record<PermAction, string>>;
46	}
