48	/** The actions the permission matrix covers. */
49	export const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;
50	export type PermAction = (typeof PERM_ACTIONS)[number];
51	
52	/** The roles that may take each action while its matrix entry is blank. */
53	export const STANDING_PERMISSIONS: Record<PermAction, string> = {
54	  open: 'clerk,steward', settle: 'clerk,steward', void: 'clerk,steward',
55	  reassign: 'steward', close: 'clerk,steward', reopen: 'steward',
56	};
57	
58	/** A setting's value in force on a date (yyyy-mm-dd): the one recorded with the latest from-date on or before it;
59	 *  `start` (the sheet's starting value) before every from-date, or when it is none. */
60	export function settingOn(settings: readonly DatedSetting[], key: string, date: string, start: string): string {
61	  let inForce: DatedSetting | undefined;
62	  for (const s of settings) {
63	    if (s.key === key && (s.from === null || s.from <= date) && (inForce === undefined || inForce.from === null
64	        || (s.from !== null && s.from > inForce.from))) inForce = s;
65	  }
66	  return inForce?.value ?? start;
67	}
