168	  protected readonly roleNames = ROLES.join(' or ');
169	  protected readonly settingsError = signal<string | null>(null);
170	  protected readonly roleError = signal<string | null>(null);
171	  protected readonly savingSettings = signal(false);
172	  protected readonly savingRole = signal(false);
173	
174	  /** The setting field last focused: with no setting changed, it is the one saved as it is. */
175	  protected lastFocused: SettingField = 'clerkLimit';
176	
177	  protected readonly settingsForm = new FormGroup({
178	    clerkLimit: new FormControl('', { nonNullable: true }),
179	    floor: new FormControl('', { nonNullable: true }),
180	    terms: new FormControl('', { nonNullable: true }),
181	    termsA: new FormControl('', { nonNullable: true }),
182	    termsB: new FormControl('', { nonNullable: true }),
183	    termsC: new FormControl('', { nonNullable: true }),
184	    latePct: new FormControl('', { nonNullable: true }),
185	    policyDate: new FormControl('', { nonNullable: true }),
186	    periodNumberingFrom: new FormControl('', { nonNullable: true }),
187	    cap: new FormControl('', { nonNullable: true }),
188	    proofThreshold: new FormControl('', { nonNullable: true }),
189	    clerkLimitFrom: new FormControl('', { nonNullable: true }),
190	    floorFrom: new FormControl('', { nonNullable: true }),
191	    termsFrom: new FormControl('', { nonNullable: true }),
192	    termsAFrom: new FormControl('', { nonNullable: true }),
193	    termsBFrom: new FormControl('', { nonNullable: true }),
194	    termsCFrom: new FormControl('', { nonNullable: true }),
195	    latePctFrom: new FormControl('', { nonNullable: true }),
196	    capFrom: new FormControl('', { nonNullable: true }),
197	    proofThresholdFrom: new FormControl('', { nonNullable: true }),
198	    perm_open: new FormControl('', { nonNullable: true }),
199	    perm_settle: new FormControl('', { nonNullable: true }),
200	    perm_void: new FormControl('', { nonNullable: true }),
201	    perm_reassign: new FormControl('', { nonNullable: true }),
202	    perm_close: new FormControl('', { nonNullable: true }),
203	    perm_reopen: new FormControl('', { nonNullable: true }),
204	  });
205	  protected readonly roleForm = new FormGroup({
206	    user: new FormControl('', { nonNullable: true }),
207	    role: new FormControl('', { nonNullable: true }),
208	  });
209	
210	  constructor() {
211	    // Each (re)load of a sheet re-reads its roles and settings from the store.
212	    toObservable(this.sheets.loaded)
213	      .pipe(
214	        switchMap((sheet) => {
215	          this.settingsError.set(null);
216	          this.roleError.set(null);
217	          this.resetSettings(sheet);
218	          return this.roles.load(sheet?.id ?? null) ?? EMPTY;
219	        }),
220	        takeUntilDestroyed(),
221	      )
222	      .subscribe({ error: () => this.roleError.set('Could not read the roles.') });
223	    // An error is removed as soon as its form is changed.
224	    this.settingsForm.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.settingsError.set(null));
225	    this.roleForm.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.roleError.set(null));
226	  }
227	
228	  protected saveSettings(): void {
229	    // A second submit before the first has answered is ignored, so it stores one change.
230	    if (this.savingSettings()) return;
231	    this.settingsError.set(null);
232	    const sheet = this.sheets.current();
233	    if (!sheet) return;
234	    const { clerkLimit, floor, terms, latePct, policyDate, periodNumberingFrom, cap, proofThreshold } = this.settingsForm.controls;
235	    const limit = clerkLimit.value.trim();
236	    const floorValue = floor.value.trim();
237	    const termsValue = terms.value.trim();
238	    const latePctValue = latePct.value.trim();
239	    const policyDateValue = policyDate.value.trim();
240	    const periodNumberingFromValue = periodNumberingFrom.value.trim();
241	    const capValue = cap.value.trim();
242	    const proofThresholdValue = proofThreshold.value.trim();
243	    // Only the settings changed in the form (a value or its from-date) are saved; with none changed, the field last
244	    // focused (else the clerk limit) is saved as it is.
245	    const unchanged = !this.settingsForm.dirty;
246	    const controls = this.settingsForm.controls;
247	    const isSaved = (field: SettingField) => controls[field].dirty
248	      || (field !== 'policyDate' && field !== 'periodNumberingFrom' && !field.startsWith('perm_')
249	        && controls[`${field as DatedField}From`].dirty)
250	      || (unchanged && this.lastFocused === field);
251	    const fromOf = (field: DatedField): string | null => controls[`${field}From` as FromField].value.trim() || null;
252	    const saveFloor = isSaved('floor');
253	    const saveTerms = isSaved('terms');
254	    const saveLatePct = isSaved('latePct');
255	    const savePolicyDate = isSaved('policyDate');
256	    const savePeriodNumberingFrom = isSaved('periodNumberingFrom');
257	    const saveLimit = isSaved('clerkLimit');
258	    const saveCap = isSaved('cap');
259	    const saveProofThreshold = isSaved('proofThreshold');
260	    if (saveLimit && limit !== '' && !LIMIT_PATTERN.test(limit)) {
261	      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
262	      return;
263	    }
264	    if (saveFloor && !LIMIT_PATTERN.test(floorValue)) {
265	      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
266	      return;
267	    }
268	    if (saveTerms && !TERMS_PATTERN.test(termsValue)) {
269	      this.settingsError.set('Type terms of 0 or more whole days.');
270	      return;
271	    }
272	    const gradeTermsSaved = GRADES.filter((g) => isSaved(GRADE_TERMS_FIELD[g]))
273	      .map((g) => ({ grade: g, value: this.settingsForm.controls[GRADE_TERMS_FIELD[g]].value.trim() }));
274	    if (gradeTermsSaved.some((t) => t.value !== '' && !TERMS_PATTERN.test(t.value))) {
275	      this.settingsError.set('Type a grade\'s terms as 0 or more whole days, or leave them blank for the sheet\'s terms.');
276	      return;
277	    }
278	    if (saveLatePct && !LATE_PCT_PATTERN.test(latePctValue)) {
279	      this.settingsError.set('Type a late percent of 0.00 or more, up to 999.99, with up to two decimals.');
280	      return;
281	    }
282	    if (savePolicyDate && policyDateValue !== '' && !(DATE_PATTERN.test(policyDateValue) && isDate(policyDateValue))) {
283	      this.settingsError.set('Type a policy date as yyyy-mm-dd, or leave it blank for the sheet\'s today.');
284	      return;
285	    }
286	    if (savePeriodNumberingFrom && periodNumberingFromValue !== ''
287	        && !(DATE_PATTERN.test(periodNumberingFromValue) && isDate(periodNumberingFromValue))) {
288	      this.settingsError.set('Type a period numbering from date as yyyy-mm-dd, or leave it blank for off.');
289	      return;
290	    }
291	    if (saveCap && capValue !== '' && !LIMIT_PATTERN.test(capValue)) {
292	      this.settingsError.set('Type a cap of 0.00 or more, with up to two decimals, or leave it blank for none.');
293	      return;
294	    }
295	    if (saveProofThreshold && proofThresholdValue !== '' && !LIMIT_PATTERN.test(proofThresholdValue)) {
296	      this.settingsError.set('Type a proof threshold of 0.00 or more, with up to two decimals, or leave it blank for none.');
297	      return;
298	    }
299	    const permsSaved = PERM_ACTIONS.filter((a) => isSaved(`perm_${a}`))
300	      .map((a) => ({ action: a, roles: controls[`perm_${a}`].value.split(',').map((r) => r.trim()).filter((r) => r !== '') }));
301	    if (permsSaved.some((p) => p.roles.some((r) => !(ROLES as readonly string[]).includes(r)))) {
302	      this.settingsError.set(`List the roles that may take an action, comma separated (${this.roleNames}), or leave it blank for the standing rule.`);
303	      return;
304	    }
305	    const datedFields: DatedField[] = ['clerkLimit', 'floor', 'terms', 'termsA', 'termsB', 'termsC', 'latePct', 'cap', 'proofThreshold'];
306	    const badFrom = datedFields.find((f) => {
307	      const from = fromOf(f);
308	      return isSaved(f) && from !== null && !(DATE_PATTERN.test(from) && isDate(from));
309	    });
310	    if (badFrom !== undefined) {
311	      this.settingsError.set('Type a from-date as yyyy-mm-dd, or leave it blank for the sheet\'s today.');
312	      return;
313	    }
314	    const saves: Observable<SheetView>[] = [];
315	    if (saveLimit) saves.push(this.sheets.setSettings(sheet.id, limit === '' ? null : limit, fromOf('clerkLimit')));
316	    if (saveFloor) saves.push(this.sheets.setFloor(sheet.id, floorValue, fromOf('floor')));
317	    if (saveTerms) saves.push(this.sheets.setTerms(sheet.id, Number(termsValue), fromOf('terms')));
318	    for (const t of gradeTermsSaved) saves.push(this.sheets.setGradeTerms(sheet.id, t.grade, t.value === '' ? null : Number(t.value), fromOf(GRADE_TERMS_FIELD[t.grade])));
319	    if (saveLatePct) saves.push(this.sheets.setLatePct(sheet.id, latePctValue, fromOf('latePct')));
320	    if (savePolicyDate) saves.push(this.sheets.setPolicyDate(sheet.id, policyDateValue === '' ? null : policyDateValue));
321	    if (savePeriodNumberingFrom) saves.push(this.sheets.setPeriodNumberingFrom(sheet.id, periodNumberingFromValue === '' ? null : periodNumberingFromValue));
322	    if (saveCap) saves.push(this.sheets.setCap(sheet.id, capValue === '' ? null : capValue, fromOf('cap')));
323	    if (saveProofThreshold) saves.push(this.sheets.setProofThreshold(sheet.id, proofThresholdValue === '' ? null : proofThresholdValue, fromOf('proofThreshold')));
324	    for (const p of permsSaved) saves.push(this.sheets.setPermission(sheet.id, p.action, p.roles.join(',')));
325	    this.savingSettings.set(true);
326	    concat(...saves).pipe(last()).subscribe({
327	      next: (saved) => {
328	        this.savingSettings.set(false);
329	        this.resetSettings(saved);
330	      },
331	      error: () => {
332	        this.savingSettings.set(false);
333	        this.settingsError.set('Could not save the settings.');
334	      },
335	    });
336	  }
337	
338	  /** Show the sheet's settings in force on its today in the form, as not yet changed, with blank from-dates. */
339	  private resetSettings(sheet: SheetView | null): void {
340	    this.settingsForm.reset({ clerkLimit: sheet?.clerkLimit ?? '', floor: sheet?.floor ?? '', terms: String(sheet?.terms ?? ''), termsA: String(sheet?.gradeTerms?.A ?? ''), termsB: String(sheet?.gradeTerms?.B ?? ''), termsC: String(sheet?.gradeTerms?.C ?? ''), latePct: sheet?.latePct ?? '', policyDate: sheet?.policyDate ?? '', periodNumberingFrom: sheet?.periodNumberingFrom ?? '', cap: sheet?.cap ?? '', proofThreshold: sheet?.proofThreshold ?? '', clerkLimitFrom: '', floorFrom: '', termsFrom: '', termsAFrom: '', termsBFrom: '', termsCFrom: '', latePctFrom: '', capFrom: '', proofThresholdFrom: '',
341	      perm_open: sheet?.permissions?.open ?? '', perm_settle: sheet?.permissions?.settle ?? '', perm_void: sheet?.permissions?.void ?? '',
342	      perm_reassign: sheet?.permissions?.reassign ?? '', perm_close: sheet?.permissions?.close ?? '', perm_reopen: sheet?.permissions?.reopen ?? '' }, { emitEvent: false });
343	  }
344	
345	  protected saveRole(): void {
346	    // A second submit before the first has answered is ignored, so it stores one record.
347	    if (this.savingRole()) return;
348	    this.roleError.set(null);
349	    const sheet = this.sheets.current();
350	    if (!sheet) return;
351	    const user = this.roleForm.controls.user.value.trim();
352	    const role = this.roleForm.controls.role.value.trim();
353	    if (!user) {
354	      this.roleError.set('Type the user name to assign a role to.');
355	      return;
356	    }
357	    if (!(ROLES as readonly string[]).includes(role)) {
358	      this.roleError.set(`Choose a role: ${this.roleNames}.`);
359	      return;
360	    }
361	    this.savingRole.set(true);
362	    this.roles.set(sheet.id, user, role as RoleName).subscribe({
363	      next: () => {
364	        this.savingRole.set(false);
365	        this.roleForm.reset({ user: '', role: '' }, { emitEvent: false });
366	      },
367	      error: () => {
368	        this.savingRole.set(false);
369	        this.roleError.set('Could not assign that role.');
370	      },
371	    });
372	  }
373	}
